# 5급 CH10 접속사 (91~100) 2차 감수
X(5, 91, r="and는 ‘그리고’(나열), or는 ‘또는’(선택), but은 ‘그러나’(대조)를 나타낸다.",
  n=["and는 ‘그리고’라 둘 중 하나를 고르는 뜻이 아니므로", "or가 ‘아니면’의 뜻으로 둘 중 하나를 고르게 하므로", "but은 대조를 나타내므로", "when은 ‘~할 때’라는 뜻이므로", "so는 ‘그래서’라는 뜻이므로"],
  st="① 우리말에서 두 말을 잇는 말을 찾는다: ‘{0}’. → ② 이 뜻의 접속사는 {1}. → ③ 정답은 {n}.",
  R=("아니면", "or(선택)"), B=("~지만", "but(대조)"), C=("~와", "and(나열)"), D=("~지만", "but(대조)"), E=("또는", "or(선택)"), F=("~하고", "and(나열)"))

X(5, 92, r="and는 같은 성격의 말을 잇는다. 형용사 and 형용사처럼 앞뒤의 품사가 같아야 한다.",
  n=["형용사라 cute와 나란히 쓸 수 있으므로", "형용사라 cute와 나란히 쓸 수 있으므로", "-ly로 끝나지만 형용사라 쓸 수 있으므로", "부사라 형용사 cute와 and로 이을 수 없으므로", "형용사라 cute와 나란히 쓸 수 있으므로"],
  st="① and 앞의 말을 본다: {0}. be동사 뒤의 형용사다. → ② and 뒤에도 형용사가 와야 한다. 부사를 찾는다. → ③ {1} 정답은 {n}.",
  R=("cute", "beautifully는 부사다. lovely는 -ly로 끝나도 형용사다."), B=("clean", "carefully는 부사다."), C=("big", "quietly는 부사다."), D=("kind", "warmly는 부사다."), E=("soft", "nicely는 부사다."),
  F=("tall", "politely는 부사다. friendly는 -ly로 끝나도 형용사다."))

X(5, 93, r="but은 대조(‘~지만’), and는 나열, or는 선택을 나타낸다. when은 ‘~할 때’, before는 ‘~하기 전에’, after는 ‘~한 후에’다.",
  n=["‘오래되었지만’은 and가 아니라 but이므로", "‘오래되었지만’은 but이고 ‘있었을 때’는 before가 아니므로", "‘있었을 때’는 after가 아니라 when이므로", "‘~지만’은 but, ‘~했을 때’는 when이므로", "‘오래되었지만’은 or가 아니므로"],
  st="① 첫 문장의 우리말: {0}. → ② 둘째 문장의 우리말: {1}. → ③ 정답은 {n}.",
  R=("‘오래되었지만’ → but", "‘있었을 때’ → when"), B=("‘피곤했지만’ → but", "‘잠자리에 들기 전에’ → before"), C=("‘아니면’ → or", "‘먹기 전에’ → before"), D=("‘보기 전에’ → before", "‘어리지만’ → but"),
  E=("‘도착하고 나서’ → after", "‘작지만’ → but"), F=("‘방과 후에’ → after", "‘전화했을 때’ → when"))

